insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"epionce","slug":"lytic-gel-cleanser","title_zh_hk":"Lytic\u6f54\u9762\u556b\u55b1","title_zh_cn":"Lytic\u6d01\u9762\u556b\u55b1","title_en":"Lytic Gel Cleanser","description_zh_hk":"<p>Lytic \u6f54\u9762\u556b\u55b1\u6709\u6548\u6e05\u9664\u6cb9\u8102\uff0c\u6b7b\u76ae\u53ca\u808c\u819a\u4e0a\u7684\u6709\u5bb3\u7d30\u83cc\uff0c\u540c\u6642\u8212\u7de9\u708e\u75c7\u4e26\u4ee4\u808c\u819a\u5e7c\u6ed1\u7d30\u7dfb\u3002\u7279\u5225\u9069\u5408\u6697\u7621\u3001\u76ae\u819a\u708e\u3001\u6fd5\u75b9\u53ca\u725b\u76ae\u766c\u7528\u8005\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548:</p>\n<p>\u2013 Epionce\u7684\u89d2\u8cea\u4fee\u5fa9\u914d\u65b9 \u2013 EpiK, \u5e6b\u52a9\u758f\u901a\u5835\u585e\u6bdb\u5b54\u7684\u6cb9\u8102\u6c61\u57a2\u3001\u7d30\u83cc\u3001\u5316\u599d\u54c1\u6b98\u7559\u7269\u53ca\u6b7b\u76ae\uff0c\u540c\u6642\u4e0d\u640d\u5bb3\u76ae\u819a\u4fdd\u8b77\u5c64\u3002</p>\n<p>\u2013 EpiK \u4ea6\u53ef\u63d0\u5347\u76ae\u819a\u5929\u7136\u4fdd\u8b77\u5c64\u7684\u5438\u6536\u80fd\u529b\uff0c\u5e6b\u52a9\u808c\u819a\u628a\u7522\u54c1\u7cbe\u83ef\u6df1\u5c64\u6ef2\u900f\u808c\u819a\u5e95\u5c64\u3002</p>\n\n<p>\u4e3b\u8981\u6210\u5206:</p>\n<p>\u2013 \u767d\u67f3\u76ae\u63d0\u53d6\u7269</p>\n<p>\u2013 \u8584\u8377</p>\n<p>\u2013 \u68d7\u5b50\u63d0\u53d6\u7269</p>","description_zh_cn":"<p>Lytic \u6d01\u9762\u556b\u55b1\u6709\u6548\u6e05\u9664\u6cb9\u8102\uff0c\u6b7b\u76ae\u53ca\u808c\u80a4\u4e0a\u7684\u6709\u5bb3\u7ec6\u83cc\uff0c\u540c\u65f6\u8212\u7f13\u708e\u75c7\u5e76\u4ee4\u808c\u80a4\u5e7c\u6ed1\u7ec6\u81f4\u3002\u7279\u522b\u9002\u5408\u6697\u75ae\u3001\u76ae\u80a4\u708e\u3001\u6e7f\u75b9\u53ca\u725b\u76ae\u7663\u7528\u8005\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548:</p>\n<p>\u2013 Epionce\u7684\u89d2\u8d28\u4fee\u590d\u914d\u65b9 \u2013 EpiK, \u5e2e\u52a9\u758f\u901a\u5835\u585e\u6bdb\u5b54\u7684\u6cb9\u8102\u6c61\u57a2\u3001\u7ec6\u83cc\u3001\u5316\u5986\u54c1\u6b8b\u7559\u7269\u53ca\u6b7b\u76ae\uff0c\u540c\u65f6\u4e0d\u635f\u5bb3\u76ae\u80a4\u4fdd\u62a4\u5c42\u3002</p>\n<p>\u2013 EpiK \u4ea6\u53ef\u63d0\u5347\u76ae\u80a4\u5929\u7136\u4fdd\u62a4\u5c42\u7684\u5438\u6536\u80fd\u529b\uff0c\u5e2e\u52a9\u808c\u80a4\u628a\u4ea7\u54c1\u7cbe\u534e\u6df1\u5c42\u6e17\u900f\u808c\u80a4\u5e95\u5c42\u3002</p>\n\n<p>\u4e3b\u8981\u6210\u5206:</p>\n<p>\u2013 \u767d\u67f3\u76ae\u63d0\u53d6\u7269</p>\n<p>\u2013 \u8584\u8377</p>\n<p>\u2013 \u67a3\u5b50\u63d0\u53d6\u7269</p>","description_en":"<p>Clears oil, dead skin and harmful bacteria while soothing inflammation. Especially suitable for acne, dermatitis, eczema and psoriasis.</p>\n<p>Key benefits</p>\n<p>\u2013 Epionce EpiK keratolytic formula unclogs pores of oil, bacteria, makeup residue and dead skin without damaging the barrier</p>\n<p>\u2013 Improves barrier absorption so actives penetrate more deeply</p>\n<p>Key ingredients</p>\n<p>\u2013 White willow bark extract</p>\n<p>\u2013 Peppermint</p>\n<p>\u2013 Date extract</p>","price_hkd":300,"stock":20,"image_paths":["/images/products/prod-14@2x.jpg"],"sort":216}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;